import{_ as t,a as r}from"./chunks/ugso_trigger_value.BNdSBQ-1.js";import{_ as s,o,c as a,a3 as n}from"./chunks/framework.BlfGB29P.js";const i="/assets/blocks-for-ha/schedule-fr.png",d="/assets/blocks-for-ha/schedule-dark-fr.png",b=JSON.parse('{"title":"Date et heure","description":"","frontmatter":{"title":"Date et heure"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/time.md","filePath":"fr/projects/blocks-for-ha/time.md","lastUpdated":1792850658000}'),c={name:"fr/projects/blocks-for-ha/time.md"};function u(l,e,p,m,h,g){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="date-et-heure" tabindex="-1">Date et heure <a class="header-anchor" href="#date-et-heure" aria-label="Permalink to &quot;Date et heure&quot;">​</a></h1><h2 id="horaires-et-declencheurs-depuis-0-1-60" tabindex="-1">Horaires et déclencheurs depuis 0.1.60 <a class="header-anchor" href="#horaires-et-declencheurs-depuis-0-1-60" aria-label="Permalink to &quot;Horaires et déclencheurs depuis 0.1.60&quot;">​</a></h2><p>Cliquer sur le champ CRON dans <strong>Déclencheurs → Horaire</strong>. Le dialogue propose <strong>Assistant / Simple / CRON</strong>, suivant les fenêtres ioBroker. Simple définit des intervalles ; Assistant propose aussi une heure précise avec des jours numériques. CRON dispose d’onglets par champ et de secondes facultatives. <strong>OK</strong> applique une règle valide ; <strong>Annuler</strong> et Échap conservent la valeur précédente. Thèmes clair/sombre et textes DE/EN/FR disponibles.</p><p><img src="'+t+'" alt="Horaire"></p><p><img src="'+i+'" alt="Dialogue CRON"></p><p><img src="'+d+'" alt="Dialogue CRON sombre"></p><p>Cinq champs : minute, heure, jour du mois, mois, jour de semaine. Six champs commencent par les secondes. Nombres, listes, plages et pas sont acceptés. Exemples : <code>*/5 * * * *</code> toutes les cinq minutes ; <code>*/30 * * * * *</code> toutes les 30 secondes ; <code>30 7 * * 1-5</code> du lundi au vendredi à 07:30. Dimanche : 0 ou 7. Home Assistant exécute dans son heure locale, sans minuterie du navigateur. Les pas suivent les champs de l’horloge : <code>*/7</code> minutes recommence à la minute 0 de chaque heure.</p><p>La sortie utilise <code>time_pattern</code> ou <code>time</code> avec <code>weekday</code>. Mois et jour du mois doivent être <code>*</code>. Dates, périodes de validité, exécution unique et plages astronomiques jour/nuit ne sont pas encore implémentés dans ce dialogue. Les règles non prises en charge sont explicitement refusées. Les règles par jours sont limitées à 2000 heures individuelles ; au-delà, elles sont refusées. Déclencheurs calendrier et conditions HA restent disponibles séparément. Le JSON du projet conserve la règle CRON ; le YAML conserve la structure HA native équivalente.</p><table tabindex="0"><thead><tr><th>Déclencheur ioBroker</th><th>Blocks for HA / équivalent HA</th></tr></thead><tbody><tr><td>Si objet / Si objets</td><td>Déclencheur d’état avec une ou plusieurs entités ; état précédent/suivant, attribut et durée. Pas d’identifiants d’objets ioBroker.</td></tr><tr><td>Déclenché par / confirmer la valeur</td><td>Pas d’équivalent ioBroker <code>ack</code> ici dans HA. Aucun bloc artificiel de confirmation.</td></tr><tr><td>↪ Valeur / Message</td><td>Nouveau bloc de données : état actuel/précédent, ID d’entité, ID/type du déclencheur, message MQTT/JSON et données d’événement. Donnée absente : <code>none</code> ; convertir les nombres si nécessaire.</td></tr><tr><td>Astro avec décalage</td><td>Lever/coucher du soleil avec décalage facultatif en minutes. Autres conditions solaires via les blocs HA natifs.</td></tr><tr><td>Horaire / CRON</td><td>Dialogue ci-dessus, exécution HA native. Pas d’enregistrement dynamique d’horaires ioBroker nommés.</td></tr><tr><td>Message reçu</td><td>Déclencheur MQTT ou événement HA avec filtre ; pas de réception directe de messages entre scripts ioBroker.</td></tr><tr><td>Message de journal</td><td>Événement HA <code>system_log_event</code>, si HA est configuré pour fournir ces événements. Aucun écouteur ioBroker dédié.</td></tr><tr><td>Événements de fichiers/enums</td><td>Pas d’équivalent direct. Utiliser une intégration HA disponible et ses événements/entités.</td></tr><tr><td>Autres déclencheurs HA natifs</td><td>MQTT, modèle, webhook, appareil, tag, conversation, zone et géolocalisation figurent directement dans <strong>Déclencheurs</strong>, sans doublons dans HA avancé.</td></tr></tbody></table><p><img src="'+r+'" alt="Données du déclencheur"></p><p>Références : <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_trigger.ts" target="_blank" rel="noreferrer">blocs ioBroker originaux</a>, <a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">déclencheurs HA natifs</a>. L’apparence suit l’original ; exécution et données restent propres à HA.</p><p>Les blocs utilisent l’heure locale et le fuseau de <strong>Home Assistant</strong>, pas l’horloge du navigateur. Une date calculée reste un objet date Jinja ; convertir explicitement avant de l’afficher ou de la sérialiser en JSON. <a href="./blocks">Images et fonctions</a>.</p><table tabindex="0"><thead><tr><th>Fonction</th><th>Comportement</th></tr></thead><tbody><tr><td>Comparaison de l’heure actuelle</td><td>Avant, avant ou égal, après, après ou égal, égal, entre ou hors de. Format <code>HH:mm</code> ou <code>HH:mm:ss</code>.</td></tr><tr><td>Comparaison avec entrée</td><td>Heure sous forme de texte raccordé. Décocher l’heure actuelle fait apparaître une entrée de date à comparer.</td></tr><tr><td>Entre deux heures</td><td>Début inclus, fin exclue, y compris à travers minuit. Bornes égales : plage vide.</td></tr><tr><td>Date actuelle</td><td><code>now()</code> de HA, avec fuseau, pour calculer ou formater.</td></tr><tr><td>Date calculée</td><td>Début du jour, du jour suivant, de la semaine (lundi), du mois ou de l’année.</td></tr><tr><td>Événement solaire</td><td>Prochain lever, coucher, aube, crépuscule, midi ou minuit solaire dans <code>sun.sun</code>. Décalage en minutes ; événement éventuellement demain.</td></tr><tr><td>Décaler une date</td><td>Ajouter/soustraire millisecondes, secondes, minutes, heures ou jours. Nombre fini requis.</td></tr><tr><td>Formater</td><td>Texte d’heure/date, ISO avec fuseau ou secondes Unix.</td></tr><tr><td>Date du jour</td><td>Comparer une date de calendrier complète, année incluse, avec le calendrier de HA.</td></tr></tbody></table><p>Une comparaison est une <strong>condition</strong>, pas un déclencheur périodique. Pour démarrer à une heure ou un événement solaire, utiliser les déclencheurs correspondants. Une valeur solaire absente provoque une erreur de modèle ; elle n’est pas remplacée silencieusement.</p><p>Les frontières de calendrier et changements d’heure suivent les calculs de HA. Pour un intervalle de durée fixe, distinguer durée écoulée et changement de jour du calendrier. Les tests vérifient notamment les plages passant par minuit et les frontières de fuseau.</p><p>Les variantes ioBroker ont servi de référence fonctionnelle ; les expressions sont une implémentation UGSo pour HA/Jinja. Voir <a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noreferrer">source ioBroker</a> et <a href="https://www.home-assistant.io/docs/configuration/templating/" target="_blank" rel="noreferrer">modèles HA</a>.</p>',16)])])}const _=s(c,[["render",u]]);export{b as __pageData,_ as default};
